export const PRIVACY_HTML: string = "<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>ShogunAgent Privacy Policy</title>\n<style>body{font:16px/1.6 system-ui,sans-serif;max-width:46rem;margin:2rem auto;padding:0 1rem;color:#111;background:#fff}\n@media (prefers-color-scheme:dark){body{color:#e8e8e8;background:#111}a{color:#8ab4ff}th,td{border-color:#444}}\ntable{border-collapse:collapse;width:100%;font-size:.92rem}th,td{border:1px solid #ccc;padding:.4rem;text-align:left;vertical-align:top}\nblockquote{margin:1rem 0;padding:.5rem 1rem;border-left:4px solid #c90;background:rgba(200,150,0,.08)}code{font-size:.9em;word-break:break-word}</style>\n</head><body>\n<h1 id=\"shogunagent-privacy-policy\">ShogunAgent Privacy Policy</h1>\n<blockquote><p><strong>DRAFT — for legal review. Not in force.</strong> This draft describes what the code in this repository actually does as of 2026-10-25. Counsel must review it, fill the placeholders marked <code>[TBD]</code>, and confirm the subprocessor list before it is published. Until then, <code>/privacy</code> serves this text with the same banner.</p></blockquote>\n<p>Last updated: 2026-10-25 (draft). Operator: Select KK <code>[TBD: registered address, company number]</code>. Contact: <code>[TBD: privacy@ address]</code>.</p>\n<h2 id=\"1-what-shogunagent-is\">1. What ShogunAgent is</h2>\n<p>ShogunAgent is a state layer for AI agents: a typed model of a person&#39;s work (people, projects, commitments, open loops) that agents read and write over MCP, REST and a CLI. It runs in two ways:</p>\n<ul><li><strong>Local (open source).</strong> The engine runs on your own machine or server. Nothing in this policy applies to data that never leaves it: we do not receive it.</li><li><strong>Hosted.</strong> We run the engine and a gateway for you at <code>api.shogunagent.dev</code>. This policy covers the hosted service.</li></ul>\n<h2 id=\"2-the-short-version\">2. The short version</h2>\n<ul><li>Your state lives in <strong>one encrypted store per principal</strong> (one SQLCipher file per person). Other customers cannot query it; access across principals happens only through access lists you set up.</li><li>The <strong>gateway never stores request or response bodies.</strong> Logs, metrics, billing records and error reports carry ids, counts, amounts and timestamps, never the content of what your agents send or receive.</li><li><strong>We do not train models on your data,</strong> and we do not let our model providers do so.</li><li><strong>Export is always free</strong> and available at any time, in an open, documented format. Deleting your data is free too.</li><li><strong>No telemetry by default.</strong> Anything beyond what is needed to run and bill the service is opt-in and counts only.</li></ul>\n<h2 id=\"3-what-we-process-and-why\">3. What we process, and why</h2>\n<table><thead><tr><th>Data</th><th>Where it lives</th><th>Why</th><th>How long</th></tr></thead><tbody><tr><td>Your state and memory (events you ingest, notes, the people / projects / commitments / open loops derived from them, their provenance)</td><td>Your principal&#39;s encrypted store</td><td>To provide the service you asked for</td><td>Until you delete it or close the principal</td></tr><tr><td>Request and response bodies passing through the gateway (<code>/mcp</code>, router runs)</td><td>Relayed in memory only; never written to disk, logs or metrics</td><td>To forward the call</td><td>Not retained</td></tr><tr><td>Account identifiers: principal id, tenant id, an optional referrer id you supply</td><td>Gateway database</td><td>To identify who owns a store and a wallet</td><td>While the principal exists</td></tr><tr><td>API keys</td><td>Gateway database, as a salted PBKDF2-SHA256 hash plus a short lookup prefix; the key itself is shown to you once and never stored</td><td>Authentication</td><td>Until the key is revoked or expires, then as long as the principal exists</td></tr><tr><td>OAuth grants for apps you connect (the app&#39;s client id URL, its redirect URI, granted scopes; codes and tokens only as SHA-256 hashes)</td><td>Gateway database</td><td>Letting MCP clients connect on your behalf</td><td>Codes: 60 seconds plus one day; tokens: until expiry plus one day</td></tr><tr><td>Billing records: wallet balance, top-ups, per-call receipts (method, tool name, unit, quantity, cost, time), disputes, monthly statements, commit contracts</td><td>Gateway database</td><td>Metering, invoicing, disputes, tax and accounting</td><td>Receipts: 400 days; closed statements and ledger entries: <code>[TBD: statutory accounting retention]</code></td></tr><tr><td>Dispute reasons you write</td><td>Gateway database (bounded to 1,000 characters)</td><td>Resolving the dispute</td><td>With the dispute record; never copied into statements</td></tr><tr><td>Payment details</td><td>Held by Stripe, not by us; we keep Stripe&#39;s session, payment and charge ids</td><td>Taking card top-ups and refunds</td><td>As billing records</td></tr><tr><td>Client IP address at registration</td><td>Used for per-IP rate limiting, stored only as a SHA-256 hash</td><td>Abuse prevention</td><td>About ten minutes after the one-hour window closes</td></tr><tr><td>Request log lines (method, route template, status, duration, a fixed event word, a hash of the key id)</td><td>Our hosting provider&#39;s log store</td><td>Operating and securing the service</td><td><code>[TBD: log retention of the hosting provider]</code></td></tr></tbody></table>\n<p>We do not sell personal data, we do not use it for advertising, and we do not build profiles of you beyond what you put into your own state.</p>\n<h2 id=\"4-model-providers-and-zero-retention\">4. Model providers and zero retention</h2>\n<p>Some operations (ingest extraction, consolidation, AI search) call a large-language-model provider. We send only the chunk needed for that call, under zero-retention terms where the provider offers them, and we never allow the provider to train on it. Bodies are relayed, not stored, on our side. Which provider handles which operation is listed in section 7.</p>\n<h2 id=\"5-your-choices-and-rights\">5. Your choices and rights</h2>\n<ul><li><strong>Export:</strong> <code>GET /v1/export</code> (or the CLI / MCP equivalent) returns your full state in the documented export format (<code>docs/api/export-v1.md</code>). It is free and never rate-limited into uselessness.</li><li><strong>Delete:</strong> deleting a principal deletes its store. Billing records we must keep by law are kept without your state content.</li><li><strong>Revoke access:</strong> revoke any API key or OAuth grant at any time; tokens minted from a revoked key stop working immediately.</li><li><strong>Statutory rights:</strong> depending on where you live (for example the EU/UK GDPR, the California CCPA/CPRA, Japan&#39;s APPI) you can ask to access, correct, delete or port your personal data, or object to processing. Write to <code>[TBD: privacy@ address]</code>. <code>[TBD: EU/UK representative, if required]</code>.</li></ul>\n<h2 id=\"6-security\">6. Security</h2>\n<p>Per-principal encrypted stores, keys stored only as hashes, secrets held in a dedicated type and never logged, tenant keys from a key management service or the environment, and a gateway that is structurally unable to log bodies. Report a vulnerability to <code>[TBD: security@ address]</code>.</p>\n<h2 id=\"7-subprocessors\">7. Subprocessors</h2>\n<p><code>[TBD: confirm each entry, its region and the contract in place before publishing.]</code></p>\n<table><thead><tr><th>Subprocessor</th><th>Purpose</th><th>Data</th></tr></thead><tbody><tr><td>Cloudflare, Inc. <code>[TBD]</code></td><td>Gateway hosting (Workers), TLS, request logs</td><td>Metadata in transit; log lines as described above</td></tr><tr><td><code>[TBD: managed Postgres provider]</code></td><td>Gateway database</td><td>Account, key-hash, billing and OAuth records</td></tr><tr><td><code>[TBD: host of the per-principal stores]</code></td><td>Hosted engine and encrypted stores</td><td>Your state</td></tr><tr><td>Stripe, Inc.</td><td>Card payments, refunds, metered commit billing</td><td>Payment details (held by Stripe), amounts, ids</td></tr><tr><td><code>[TBD: model providers, e.g. OpenAI, Anthropic]</code></td><td>Extraction, consolidation, AI search</td><td>The chunk needed for one call, under zero retention</td></tr></tbody></table>\n<p>We will give <code>[TBD: notice period]</code> notice before adding a subprocessor that processes your state.</p>\n<h2 id=\"8-international-transfers\">8. International transfers</h2>\n<p><code>[TBD: transfer mechanism (SCCs / UK addendum / APPI cross-border rules) and the regions used.]</code></p>\n<h2 id=\"9-children\">9. Children</h2>\n<p>The service is not directed to children under 16 and we do not knowingly collect their data.</p>\n<h2 id=\"10-changes\">10. Changes</h2>\n<p>We will post changes here and, for material changes, notify account holders <code>[TBD: how and how far in advance]</code>.</p>\n</body></html>\n";
export const TERMS_HTML: string = "<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>ShogunAgent Terms of Service</title>\n<style>body{font:16px/1.6 system-ui,sans-serif;max-width:46rem;margin:2rem auto;padding:0 1rem;color:#111;background:#fff}\n@media (prefers-color-scheme:dark){body{color:#e8e8e8;background:#111}a{color:#8ab4ff}th,td{border-color:#444}}\ntable{border-collapse:collapse;width:100%;font-size:.92rem}th,td{border:1px solid #ccc;padding:.4rem;text-align:left;vertical-align:top}\nblockquote{margin:1rem 0;padding:.5rem 1rem;border-left:4px solid #c90;background:rgba(200,150,0,.08)}code{font-size:.9em;word-break:break-word}</style>\n</head><body>\n<h1 id=\"shogunagent-terms-of-service\">ShogunAgent Terms of Service</h1>\n<blockquote><p><strong>DRAFT — for legal review. Not in force.</strong> This draft is written to match how the service is actually built and billed as of 2026-10-25. Counsel must review it, fill the placeholders marked <code>[TBD]</code>, and settle governing law before it is published. Until then, <code>/terms</code> serves this text with the same banner.</p></blockquote>\n<p>Last updated: 2026-10-25 (draft). These terms are between you and Select KK <code>[TBD: registered address]</code> (&quot;we&quot;).</p>\n<h2 id=\"1-the-service\">1. The service</h2>\n<p>ShogunAgent gives AI agents a shared, typed model of a person&#39;s work, read and written over MCP, REST and a CLI, with permission tiers on every action. The open-source engine is licensed separately under Apache-2.0; these terms cover the <strong>hosted</strong> service at <code>api.shogunagent.dev</code> and its gateway, router and wallet.</p>\n<h2 id=\"2-accounts-principals-and-keys\">2. Accounts, principals and keys</h2>\n<ul><li>An agent may register a principal itself (<code>POST /v1/agents</code>). Whoever controls that principal&#39;s keys is responsible for its use. If an agent registers on your behalf, you are bound by these terms when you use the result.</li><li>Keep keys secret. A key is shown once; we store only its hash and cannot recover it. Revoke a key you believe is exposed; access tokens minted from it stop working at once.</li><li>Apps you connect over OAuth act with the scopes you granted and never with <code>admin</code>. You can revoke a grant at any time.</li></ul>\n<h2 id=\"3-permission-tiers\">3. Permission tiers</h2>\n<p>Reads are L1. Writes to your own data are L2. Anything that sends, posts, pays or creates something outside your store is L3 and waits for an explicit human approval. We do not offer a setting that turns an L3 action into an automatic one. You are responsible for the approvals you give.</p>\n<h2 id=\"4-prices-wallet-and-payment\">4. Prices, wallet and payment</h2>\n<ul><li><strong>Usage-based, no subscription.</strong> Prices are published at <code>/.well-known/pricing.json</code>, which is generated from the same table that meters your calls. State reads, remote approvals, export and deletion cost nothing.</li><li><strong>Prepaid wallet.</strong> Metered calls draw from a prepaid micro-USD balance. When the balance or a hard cap would be exceeded, the call is refused with <code>402</code> before anything happens; nothing is charged for a refused call, and failed calls and empty results cost nothing.</li><li><strong>Caps.</strong> Every key and principal has daily and monthly hard caps. Defaults are conservative; you may lower them at any time.</li><li><strong>Top-ups</strong> are taken by card through Stripe. A new principal receives a free allowance, which has no cash value.</li><li><strong>Annual commits.</strong> An enterprise customer may agree a commit contract (an amount over a period) with a 10–25% discount, applied to every metered call during the period; receipts show both prices. Usage past the committed amount is billed monthly in arrears at the same discount, if the contract says so. <code>[TBD: invoicing, payment terms and what happens to unused commit at the end of the period.]</code></li><li><strong>Statements and disputes.</strong> You can download a monthly statement in JSON or CSV at any time; once a month closes, its statement is fixed and carries a checksum. Dispute any receipt through the API within <code>[TBD: dispute window, e.g. 60 days]</code>; a dispute we accept is credited to your wallet.</li><li><strong>Refunds.</strong> Unused prepaid balance is refundable <code>[TBD: conditions]</code>; refunds go back to the original card through Stripe and are deducted from the wallet.</li><li><strong>Taxes.</strong> Prices exclude taxes. <code>[TBD: tax handling.]</code></li></ul>\n<h2 id=\"5-your-data\">5. Your data</h2>\n<p>You own your data. We process it only to provide the service, as described in the Privacy Policy (<code>/privacy</code>). We do not train models on it. You can export everything, free, at any time, in the documented open format, and delete it.</p>\n<h2 id=\"6-acceptable-use\">6. Acceptable use</h2>\n<p>Do not use the service to break the law, to infringe others&#39; rights, to process data you have no right to process, to attack or overload the service or the providers behind the router, or to evade caps, rate limits or permission tiers. We may suspend a key or principal that does, with notice where we can give it.</p>\n<h2 id=\"7-third-party-tools-through-the-router\">7. Third-party tools through the router</h2>\n<p>The router can run tools operated by third parties. Their price, behaviour and terms are theirs; the router publishes each tool&#39;s price and ranking breakdown and labels our own first-party tools. A tool run that fails costs nothing.</p>\n<h2 id=\"8-availability-and-changes\">8. Availability and changes</h2>\n<p>We publish live status at <code>/.well-known/status.json</code>. We aim for high availability but, outside a signed enterprise agreement, offer no service-level guarantee. We may change prices with <code>[TBD: notice period]</code> notice published in <code>/.well-known/pricing.json</code>; a call is always charged at the price in force when it was made.</p>\n<h2 id=\"9-warranties-and-liability\">9. Warranties and liability</h2>\n<p><code>[TBD: disclaimer of warranties, limitation of liability (for example capped at the amounts paid in the preceding twelve months), indemnities.]</code></p>\n<h2 id=\"10-termination\">10. Termination</h2>\n<p>You may stop using the service at any time; export first. We may terminate for material breach. On termination, unused prepaid balance is handled as in section 4, and your data is deleted after <code>[TBD: grace period]</code> unless the law requires us to keep billing records.</p>\n<h2 id=\"11-governing-law\">11. Governing law</h2>\n<p><code>[TBD: governing law and venue.]</code></p>\n<h2 id=\"12-contact\">12. Contact</h2>\n<p><code>[TBD: support and legal contact addresses.]</code></p>\n</body></html>\n";
